/**
 * Encrypted storage for secrets (AI keys, endpoints). Everything is AES-256-GCM via WebCrypto, with a fresh random
 * IV per write and the app/version bound in as additional authenticated data, so a ciphertext can't be tampered with
 * or swapped between uses.
 *
 * Two protection modes:
 *  - "device":     a random AES key generated by the browser and stored in IndexedDB as a NON-EXTRACTABLE CryptoKey.
 *                  Its bytes can never be read or exported, so a copied/dumped localStorage is useless on its own.
 *                  No password to type. Anything that can run script on this site while you're signed in could still
 *                  ask the browser to decrypt, which is the limit of any scheme without a secret you hold.
 *  - "passphrase": a key derived from your passphrase with PBKDF2-SHA256 (600,000 rounds, random salt). The passphrase
 *                  and the derived key are never written anywhere; they live in memory until the tab closes.
 *                  Without the passphrase the data cannot be decrypted by anyone, including this app.
 */

export type Protection = "device" | "passphrase";

export interface Envelope {
  v: 1;
  mode: Protection;
  /** base64 */
  iv: string;
  ct: string;
  salt?: string;
  iter?: number;
}

export type VaultErrorCode = "locked" | "wrong-passphrase" | "key-lost" | "corrupt" | "unsupported";
export class VaultError extends Error {
  constructor(public code: VaultErrorCode, message: string) {
    super(message);
  }
}

/** Where the device key lives. Swappable so tests can run without a browser. */
export interface KeyStore {
  get(): Promise<CryptoKey | undefined>;
  set(key: CryptoKey): Promise<void>;
  delete(): Promise<void>;
}

export const PBKDF2_ITERATIONS = 600_000;
const AAD = new TextEncoder().encode("system-learn:ai:v1");

const toB64 = (u: Uint8Array) => {
  let s = "";
  for (let i = 0; i < u.length; i += 0x8000) s += String.fromCharCode(...u.subarray(i, i + 0x8000));
  return btoa(s);
};
const fromB64 = (s: string) => Uint8Array.from(atob(s), (c) => c.charCodeAt(0));
const bytes = (u: Uint8Array) => u as unknown as BufferSource;

export function isEnvelope(v: unknown): v is Envelope {
  const e = v as Envelope | null;
  return !!e && e.v === 1 && (e.mode === "device" || e.mode === "passphrase") && typeof e.iv === "string" && typeof e.ct === "string";
}

export function cryptoAvailable(): boolean {
  return typeof crypto !== "undefined" && !!crypto.subtle && typeof crypto.getRandomValues === "function";
}

/** The browser-backed device key store (IndexedDB). */
export const idbKeyStore: KeyStore = (() => {
  const DB = "system-learn-vault";
  const STORE = "keys";
  const ID = "device-v1";
  const open = () =>
    new Promise<IDBDatabase>((resolve, reject) => {
      const req = indexedDB.open(DB, 1);
      req.onupgradeneeded = () => req.result.createObjectStore(STORE);
      req.onsuccess = () => resolve(req.result);
      req.onerror = () => reject(req.error);
    });
  const run = async <T>(mode: IDBTransactionMode, fn: (s: IDBObjectStore) => IDBRequest<T>) => {
    const db = await open();
    try {
      return await new Promise<T>((resolve, reject) => {
        const tx = db.transaction(STORE, mode);
        const req = fn(tx.objectStore(STORE));
        tx.oncomplete = () => resolve(req.result);
        tx.onerror = () => reject(tx.error);
        tx.onabort = () => reject(tx.error);
      });
    } finally {
      db.close();
    }
  };
  return {
    get: () => run("readonly", (s) => s.get(ID)) as Promise<CryptoKey | undefined>,
    set: async (key) => void (await run("readwrite", (s) => s.put(key, ID))),
    delete: async () => void (await run("readwrite", (s) => s.delete(ID))),
  };
})();

export class Vault {
  /** key derived from the passphrase this session; never persisted */
  private pass: { key: CryptoKey; salt: string; iter: number } | null = null;

  constructor(private keys: KeyStore = idbKeyStore) {}

  /** True when a passphrase-protected envelope can be opened without asking again. */
  isUnlocked(env: Envelope): boolean {
    return env.mode === "device" || (!!this.pass && this.pass.salt === env.salt);
  }

  hasPassphraseSession(): boolean {
    return !!this.pass;
  }

  lock() {
    this.pass = null;
  }

  /** Remove the device key, so anything encrypted with it becomes unrecoverable. */
  async destroy() {
    this.pass = null;
    try {
      await this.keys.delete();
    } catch {
      /* nothing stored, or storage blocked */
    }
  }

  private async deriveKey(passphrase: string, salt: Uint8Array, iter: number): Promise<CryptoKey> {
    const base = await crypto.subtle.importKey("raw", new TextEncoder().encode(passphrase.normalize("NFKC")), "PBKDF2", false, ["deriveKey"]);
    return crypto.subtle.deriveKey({ name: "PBKDF2", hash: "SHA-256", salt: bytes(salt), iterations: iter }, base, { name: "AES-GCM", length: 256 }, false, ["encrypt", "decrypt"]);
  }

  private async deviceKey(create: boolean): Promise<CryptoKey | undefined> {
    let key = await this.keys.get();
    if (!key && create) {
      key = await crypto.subtle.generateKey({ name: "AES-GCM", length: 256 }, false, ["encrypt", "decrypt"]);
      await this.keys.set(key);
    }
    return key;
  }

  /**
   * Encrypt `plain`. For "passphrase", pass the passphrase the first time (new salt, new key); afterwards the session key
   * is reused, so re-saving doesn't need it typed again.
   */
  async seal(plain: string, mode: Protection, passphrase?: string): Promise<Envelope> {
    if (!cryptoAvailable()) throw new VaultError("unsupported", "This browser can't encrypt (WebCrypto needs a secure https or localhost page).");
    const iv = crypto.getRandomValues(new Uint8Array(12));
    let key: CryptoKey | undefined;
    let extra: Pick<Envelope, "salt" | "iter"> = {};
    if (mode === "device") {
      key = await this.deviceKey(true);
    } else if (passphrase) {
      const salt = crypto.getRandomValues(new Uint8Array(16));
      key = await this.deriveKey(passphrase, salt, PBKDF2_ITERATIONS);
      this.pass = { key, salt: toB64(salt), iter: PBKDF2_ITERATIONS };
      extra = { salt: this.pass.salt, iter: PBKDF2_ITERATIONS };
    } else if (this.pass) {
      key = this.pass.key;
      extra = { salt: this.pass.salt, iter: this.pass.iter };
    } else {
      throw new VaultError("locked", "Enter your passphrase first.");
    }
    const ct = await crypto.subtle.encrypt({ name: "AES-GCM", iv: bytes(iv), additionalData: bytes(AAD) }, key!, new TextEncoder().encode(plain));
    return { v: 1, mode, iv: toB64(iv), ct: toB64(new Uint8Array(ct)), ...extra };
  }

  /** Decrypt an envelope. Throws a VaultError saying why it couldn't. */
  async open(env: Envelope, passphrase?: string): Promise<string> {
    if (!cryptoAvailable()) throw new VaultError("unsupported", "This browser can't decrypt (WebCrypto needs a secure https or localhost page).");
    let key: CryptoKey | undefined;
    let derived: { key: CryptoKey; salt: string; iter: number } | null = null;
    if (env.mode === "device") {
      key = await this.deviceKey(false);
      if (!key) throw new VaultError("key-lost", "The encryption key for this device is gone (site data was cleared), so the saved key can't be recovered. Add it again.");
    } else {
      if (!env.salt || !env.iter) throw new VaultError("corrupt", "The saved data is damaged.");
      if (passphrase) {
        derived = { key: await this.deriveKey(passphrase, fromB64(env.salt), env.iter), salt: env.salt, iter: env.iter };
        key = derived.key;
      } else if (this.pass && this.pass.salt === env.salt) key = this.pass.key;
      else throw new VaultError("locked", "Enter your passphrase to unlock the saved key.");
    }
    try {
      const pt = await crypto.subtle.decrypt({ name: "AES-GCM", iv: bytes(fromB64(env.iv)), additionalData: bytes(AAD) }, key, bytes(fromB64(env.ct)));
      if (derived) this.pass = derived;
      return new TextDecoder().decode(pt);
    } catch {
      throw env.mode === "passphrase"
        ? new VaultError("wrong-passphrase", "Wrong passphrase (or the saved data was altered).")
        : new VaultError("corrupt", "The saved data couldn't be decrypted. It may have been altered. Add the key again.");
    }
  }
}
